param([Parameter(Mandatory=$true)][string]$Jar,[Parameter(Mandatory=$true)][string]$ResourceDir,[Parameter(Mandatory=$true)][string]$LocaleDir)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$required=@('iped-viewer-messages.properties','iped-viewer-messages_pt_BR.properties')
foreach($name in $required){$p=Join-Path $ResourceDir $name;if(!(Test-Path -LiteralPath $p)){throw "Recurso ausente: $p"};$text=[IO.File]::ReadAllText($p);if($text -notmatch '(?m)^ChatCapturePanel\.IncludeAnnotations='){throw "Chave obrigatoria ausente em $name"};if($name -eq 'iped-viewer-messages.properties' -and $text -notmatch '(?m)^HexViewerPlus\.appName='){throw 'Bundle base sem HexViewerPlus.appName'}}
$zip=[IO.Compression.ZipFile]::Open($Jar,[IO.Compression.ZipArchiveMode]::Update)
try {foreach($name in $required){$old=$zip.GetEntry($name);if($old){$old.Delete()};[IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip,(Join-Path $ResourceDir $name),$name,[IO.Compression.CompressionLevel]::Optimal)|Out-Null}} finally {$zip.Dispose()}
foreach($name in $required){$target=Join-Path $LocaleDir $name;$source=Join-Path $ResourceDir $name;if(!(Test-Path -LiteralPath $target)){throw "Locale do IPED nao encontrado: $target"};$current=[IO.File]::ReadAllText($target);$add=[Collections.Generic.List[string]]::new();foreach($line in [IO.File]::ReadAllLines($source)){if(!$line -or $line.StartsWith('#') -or !$line.Contains('=')){continue};$key=$line.Substring(0,$line.IndexOf('='));if($current -notmatch ('(?m)^'+[regex]::Escape($key)+'=')){$add.Add($line)}};if($add.Count){$backup="$target.bak-$(Get-Date -Format yyyyMMdd-HHmmss)";Copy-Item -LiteralPath $target -Destination $backup;$updated=$current.TrimEnd()+[Environment]::NewLine+($add -join [Environment]::NewLine)+[Environment]::NewLine;[IO.File]::WriteAllText($target,$updated,[Text.UTF8Encoding]::new($false))}}
$z=[IO.Compression.ZipFile]::OpenRead($Jar);try{foreach($name in $required){$e=$z.GetEntry($name);if(!$e){throw "Bundle ausente no JAR: $name"};$r=[IO.StreamReader]::new($e.Open());try{$t=$r.ReadToEnd();if($t -notmatch '(?m)^ChatCapturePanel\.IncludeAnnotations='){throw "Chave de plugin ausente: $name"}}finally{$r.Dispose()}}}finally{$z.Dispose()}
